findings.recommendation:
Wrap `connect` in a try/catch that strips the body from the error before re-throwing, e.g.

  try {
    const data = await useApi()<Bot>(`/api/v1/projects/${projectId}/bot/connect`, { method: 'POST', body: { token } })
    current.value = data
    return data
  } catch (err: unknown) {
    if (err && typeof err === 'object' && 'options' in err) {
      const opts = (err as { options?: { body?: unknown } }).options
      if (opts && 'body' in opts) opts.body = '[REDACTED]'
    }
    throw err
  }

Alternatively, document this contract loudly in the JSDoc on `connect` so reviewers reject any future caller that logs the raw error.
